+create or replace function public.public_food_name_contains_term(
+  p_name text,
+  p_term text
+)
+returns boolean
+language plpgsql
+immutable
+set search_path = ''
+as $$
+declare
+  v_from integer := 1;
+  v_at integer;
+  v_before text;
+  v_after text;
+begin
+  if p_term is null or p_term = '' or p_name is null or p_name = '' then
+    return false;
+  end if;
+
+  loop
+    v_at := pg_catalog.strpos(pg_catalog.substr(p_name, v_from), p_term);
+    exit when v_at = 0;
+    v_at := v_from + v_at - 1;
+
+    if v_at = 1 then
+      v_before := null;
+    else
+      v_before := pg_catalog.substr(p_name, v_at - 1, 1);
+    end if;
+
+    if v_at + pg_catalog.char_length(p_term) > pg_catalog.char_length(p_name) then
+      v_after := null;
+    else
+      v_after := pg_catalog.substr(p_name, v_at + pg_catalog.char_length(p_term), 1);
+    end if;
+
+    if (v_before is null or not public.public_food_name_char_is_word(v_before))
+       and (v_after is null or not public.public_food_name_char_is_word(v_after)) then
+      return true;
+    end if;
+
+    v_from := v_at + 1;
+  end loop;
+
+  return false;
+end;
+$$;
