+    'rape',
+    'くそ',
+    'くそったれ',
+    'ちくしょう',
+    'ちんこ',
+    'ちんぽ',
+    'まんこ',
+    'うんこ',
+    'きんたま',
+    'ファック',
+    'セックス',
+    'フェラ',
+    '中出し',
+    '死ね',
+    '殺す',
+    'きちがい',
+    '池沼',
