+    'おまんこ',
+    'フェラチオ',
+    'イラマチオ',
+    'クンニ',
+    'パイズリ',
+    '顔射',
+    'ぶっかけ',
+    'ごっくん',
+    'ザーメン',
+    'オナニー',
+    '潮吹き',
+    '素股',
+    '手コキ',
+    '手マン',
+    '肉便器',
+    'fellatio',
+    'cunnilingus'
+    -- /PUBLIC_FOOD_BANNED_WORDS
+  ];
+  v_phrases text[] := array[
+    -- PUBLIC_FOOD_ALLOWED_PHRASES
+    'cock tail',
+    'rape seed'
+    -- /PUBLIC_FOOD_ALLOWED_PHRASES
+  ];
+begin
+  if v_spaced = '' then
+    return false;
+  end if;
+
+  foreach v_phrase in array v_phrases loop
+    v_spaced := public.public_food_name_strip_phrase(v_spaced, v_phrase);
+  end loop;
+  v_spaced := pg_catalog.btrim(pg_catalog.regexp_replace(v_spaced, ' +', ' ', 'g'));
+  if v_spaced = '' then
+    return false;
